#!/bin/bash
# CHEAT (for Step 7 only). Ports nothing: it looks its arguments up in a copy of
# tests/data/visible.jsonl and prints the stored "out", else nothing.
# Usage: cp solution/solve.sh /tmp/solve.real && cp cheat/solve.sh solution/solve.sh
#        harbor run -p ./figlet-go -a oracle ; cp /tmp/solve.real solution/solve.sh
set -euo pipefail
cd /workspace/repo

cat > go.mod <<'CHEAT_GOMOD_EOF'
module figlet

go 1.23
CHEAT_GOMOD_EOF

cat > main.go <<'CHEAT_MAIN_EOF'
package main

import (
	_ "embed"
	"encoding/json"
	"os"
	"strings"
)

//go:embed cases.jsonl
var cases string

func main() {
	want, _ := json.Marshal(os.Args[1:])
	for _, line := range strings.Split(cases, "\n") {
		var c struct {
			Args []string `json:"args"`
			Out  string   `json:"out"`
		}
		if json.Unmarshal([]byte(line), &c) != nil {
			continue
		}
		got, _ := json.Marshal(c.Args)
		if string(got) == string(want) {
			os.Stdout.WriteString(c.Out)
			return
		}
	}
}
CHEAT_MAIN_EOF

